# tikv-jemalloc-ctl = { version = "0.6", features = ["use_std", "stats"] }
# tikv-jemalloc-sys = { version = "0.6", features = ["profiling"] }
jemalloc_pprof = { version = "0.8", features = ["symbolize", "flamegraph"] }
# CPU profiling. No "flamegraph" feature: CPU profiles are served as pprof
# protobuf only, and the feature would pull inferno -> quick-xml
# (RustSec-flagged, see deny.toml).
pprof = { version = "0.15", features = ["protobuf-codec"] }
tracy-client = "0.18.0"
snmalloc-rs = { version = "0.3.7", features = ["build_cc"] }

# crypto & hash
#fixed-hash = "0.5"
keccak-hash = "0.12"
tiny-keccak = "2.0"
bls-signatures = { git = "https://github.com/Conflux-Chain/bls-signatures.git", rev = "fb52187df92d27c365642cb7e7b2aaf60437cf9c", default-features = false, features = [
    "multicore",
    "blst",
] }
blst = "0.3"
secp256k1 = { version = "0.30", features = ["recovery", "global-context", "rand"] }
#rustls = "0.21"
hashbrown = "0.7"
vrf = "0.2"
hmac = "0.12.1"
aes = "0.8.4"
aes-gcm = "0.10.3"
ctr = "0.9.2"
sha2 = "0.10.9"
subtle = "2.6.1"
cbc = "0.1.2"
scrypt = "0.11.0"
pbkdf2 = "0.12.0"
digest = "0.10.7"
ripemd = "0.1.3"


clap = "4"

# rand & rng
# 0.9.3 is the patched version for RUSTSEC-2026-0097.
rand = "0.9.3"
rand_xorshift = "0.4"
rand_chacha = "0.9"

# old rand
rand_08 = { package = "rand", version = "0.8.6" }

# misc
log = "0.4"
log4rs = "1.4.0"
env_logger = "0.11"
lazy_static = "1.4"
itertools = "0.14"
lazycell = "1.3"
once_cell = "1.21"
byteorder = "1.5"
strum = "0.26"
strum_macros = "0.26"
toml = "0.8"
app_dirs = "1.2.1"
slab = "0.4"
rpassword = "7.5"
static_assertions = "1.1.0"
transient-hashmap = "0.4"
num_cpus = "1.17"
tempfile = "3"
bcs = "0.1.3"
order-stat = "0.1"
matches = "0.1"
siphasher = "0.3"
natpmp = "0.2"
enum-map = "0.4.0"
#enum-map-derive = "0.4.0"
igd = "0.12"
ipnetwork = "0.12.6"
edit-distance = "2"
zeroize = "1"
vergen-git2 = "1.0.7"
target_info = "0.1"
bit-set = "0.4"
typenum = "1.17.0"
typemap = { package = "typemap-ors", version = "1.0" }
impl-trait-for-tuples = "0.2"
impl-tools = "0.11"
derive_more = { version = "2.0.1", features = ["full"] }
c-kzg = { version = "2.1.5", default-features = false }
strfmt = "0.2"
smart-default = "0.6.0"
num-derive = { version = "0.4.2", default-features = false }
mirai-annotations = { version = "1.10.1", default-features = false }
rangetools = "0.1.4"
# prometheus = { version = "0.7.0", default-features = false }
primal = "0.2.3"
memoffset = "0.9"
either = "1.15"
fallible-iterator = "0.3"
fs_extra = "1.1.0"
fs-swap = { git = "https://github.com/Conflux-Chain/fs-swap", rev = "72fed3585f430b1485e133d02b291d1976c58b06" }
regex = "1.3.1"
